  2102  /* Returns 0 <= i < len for key found. Returns -1-len < i <= -1 for key
  2103   * not found, but with insertion point -1-i. */
  2104  static int
  2105  pdf_dict_finds(fz_context *ctx, pdf_obj *obj, const char *key)
  2106  {
  2107          int len = DICT(obj)->len;
  2108          if ((obj->flags & PDF_FLAGS_SORTED) && len > 0)
  2109          {
  2110                  int l = 0;
  2111                  int r = len - 1;
  2112
  2113                  if (strcmp(pdf_to_name(ctx, DICT(obj)->items[r].k), key) < 0)
  2114                  {
  2115                          return -1 - (r+1);
  2116                  }
  2117
  2118                  while (l <= r)
  2119                  {
  2120                          int m = (l + r) >> 1;
  2121                          int c = -strcmp(pdf_to_name(ctx, DICT(obj)->items[m].k), key);
  2122                          if (c < 0)
  2123                                  r = m - 1;
  2124                          else if (c > 0)
  2125                                  l = m + 1;
  2126                          else
  2127                                  return m;
  2128                  }
  2129                  return -1 - l;
  2130          }
  2131
  2132          else
  2133          {
  2134                  int i;
  2135                  for (i = 0; i < len; i++)
  2136                          if (strcmp(pdf_to_name(ctx, DICT(obj)->items[i].k), key) == 0)
  2137                                  return i;
  2138
  2139                  return -1 - len;
  2140          }
  2141  }
