  2160                          int m = (l + r) >> 1;
  2161                          int c;
  2162
  2163                          k = DICT(obj)->items[m].k;
  2164                          c = (k < PDF_LIMIT ? (char *)key-(char *)k : -strcmp(NAME(k)->n, PDF_NAME_LIST[(intptr_t)key]));
  2165                          if (c < 0)
  2166                                  r = m - 1;
  2167                          else if (c > 0)
  2168                                  l = m + 1;
  2169                          else
  2170                                  return m;
  2171                  }
  2172                  return -1 - l;
  2173          }
  2174          else
  2175          {
